'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { ThemeToggle } from './ThemeToggle';

export default function Navbar() {
  const pathname = usePathname();
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', href: '/' },
    { name: 'About', href: '/about' },
    { name: 'Services', href: '/services' },
    { name: 'Contact', href: '/contact' },
  ];

  return (
    <div className="fixed bottom-0 inset-x-0 z-50">
      <nav className="bg-[#000000]/95 backdrop-blur-xl border-t border-white/5 px-8 py-8 flex items-center justify-between">
        <div className="flex items-center gap-16">
          <Link href="/" className="group flex items-center gap-2">
            <span className="text-2xl font-black text-[#F2F2F2] tracking-tighter">SYNTAX<span className="text-[#B6B09F]">WEB</span></span>
          </Link>

          <div className="hidden md:flex items-center gap-12 border-l border-white/5 pl-16">
            {navLinks.map((link) => {
              const isActive = pathname === link.href;
              return (
                <Link
                  key={link.name}
                  href={link.href}
                  className={`text-[10px] font-black uppercase tracking-[0.4em] transition-all duration-500
                    ${isActive ? 'text-[#B6B09F]' : 'text-gray-600 hover:text-[#F2F2F2]'}`}
                >
                  {link.name}
                </Link>
              );
            })}
          </div>
        </div>

        <div className="flex items-center gap-12">
          <Link
            href="/admin/login"
            className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-600 hover:text-[#F2F2F2] transition-colors"
          >
            Partners
          </Link>
          <Link
            href="/contact"
            className="px-12 py-5 bg-[#F2F2F2] text-[#000000] text-[10px] font-black uppercase tracking-[0.4em] rounded-none hover:bg-[#B6B09F] transition-all duration-700 font-black"
          >
            Start Project
          </Link>
        </div>
      </nav>
    </div>
  );
}

